    }

    this.sides[this.viewport.currentSide - 1].getElementsByClassName('cube-image')[0].className = 'cube-image active';

  }

  cube = new Cube({
    viewport: viewport,
    element: document.getElementsByClassName('cube')[0]
  });
}
